.topic-cta { background: var(--navy); border-color: var(--navy); color: #fff; }
.topic-cta .topic-ic { background: rgba(255, 255, 255, .1); color: var(--sky-light); }
.topic-cta .muted { color: rgba(255, 255, 255, .78); }

/* ---------- Cart ---------- */
.cart-head { display: flex; align-items: center; justify-content: space-between; gap: 24px; flex-wrap: wrap; padding-bottom: 8px; }
.progress-steps { display: flex; align-items: center; gap: 8px; font-size: 14px; font-weight: 600; color: var(--muted); }
.progress-steps li { display: inline-flex; align-items: center; gap: 8px; }
.progress-steps li + li::before { content: ""; width: 32px; height: 2px; background: var(--border); margin-right: 4px; }
.progress-steps span { display: inline-grid; place-items: center; width: 28px; height: 28px; border-radius: 50%; border: 1.5px solid var(--control); font-size: 13px; background: #fff; }
.progress-steps .is-current { color: var(--navy); }
.progress-steps .is-current span { background: var(--navy); border-color: var(--navy); color: #fff; }
.progress-steps .is-done { color: var(--navy); }
.progress-steps .is-done span { background: var(--sky); border-color: var(--sky); color: var(--navy); }
.cart-section { padding: 24px 0 var(--section); }
.cart-layout { display: grid; grid-template-columns: minmax(0, 1fr) 380px; gap: 40px; align-items: start; }
.cart-main { display: flex; flex-direction: column; align-items: flex-start; gap: 24px; min-width: 0; }
.ship-meter { display: flex; align-items: center; gap: 16px; width: 100%; padding: 16px 20px; background: var(--page); border-radius: var(--r-lg); }
.ship-meter-body { flex: 1; display: grid; gap: 8px; font-size: 15px; }
.cart-list { width: 100%; border-top: 1px solid var(--border); }
.cart-item { display: grid; grid-template-columns: 104px minmax(0, 1fr) auto 110px; grid-template-areas: "thumb info qty total" "thumb info qty remove"; align-items: center; gap: 4px 24px; padding: 24px 0; border-bottom: 1px solid var(--border); }
.cart-thumb { grid-area: thumb; display: block; border-radius: var(--r-md); background: var(--page); align-self: start; }
.cart-thumb .visual { aspect-ratio: 1; }
.cart-info { grid-area: info; display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.cart-title { font-size: 17px; font-weight: 700; line-height: 1.35; }
.cart-title:hover { text-decoration: underline; text-underline-offset: 3px; }
.cart-delivery { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 600; margin-top: 6px; }
.cart-qty { grid-area: qty; display: flex; flex-direction: column; align-items: center; gap: 4px; }
.cart-line-total { grid-area: total; text-align: right; font-size: 18px; align-self: end; }
.cart-remove { grid-area: remove; justify-self: end; align-self: start; color: var(--muted); }
.cart-remove:hover { color: var(--navy); }
.cross-sell-slot { width: 100%; }
.cross-sell { width: 100%; padding: 24px; border: 1px solid var(--border); border-radius: var(--r-lg); }
.cross-list { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; margin-top: 16px; }
.cross-item { display: grid; grid-template-columns: 72px minmax(0, 1fr); grid-template-areas: "thumb body" "thumb btn"; gap: 8px 14px; align-items: start; padding: 12px; background: var(--page); border-radius: var(--r-md); }
.cross-thumb { grid-area: thumb; display: block; background: #fff; border-radius: var(--r-md); }
.cross-thumb .visual { aspect-ratio: 1; }
.cross-body { grid-area: body; display: flex; flex-direction: column; font-size: 14px; line-height: 1.4; }
.cross-body .price { font-size: 16px; margin-top: 2px; }
.cross-item .btn { grid-area: btn; justify-self: start; height: 36px; font-size: 14px; }
.summary { position: sticky; top: 104px; display: flex; flex-direction: column; gap: 16px; padding: 28px; background: var(--page); border-radius: var(--r-lg); }
.sum-rows { display: grid; gap: 10px; font-size: 15px; }
.sum-rows > div { display: flex; justify-content: space-between; gap: 16px; }
.sum-rows dt { color: var(--muted); }
.sum-rows dd { font-weight: 600; }
.sum-discount dd { color: var(--navy); }
.sum-total { display: flex; justify-content: space-between; align-items: baseline; padding-top: 16px; border-top: 1px solid rgba(11, 37, 69, .15); font-size: 18px; font-weight: 700; }
.sum-total strong { font-size: 26px; }
.summary > .t-cap { margin-top: -10px; }
.promo { border: 1px solid var(--border); border-radius: var(--r-md); background: #fff; }
.promo summary { display: flex; align-items: center; gap: 8px; min-height: 48px; padding: 0 14px; font-weight: 600; font-size: 15px; cursor: pointer; list-style: none; }
.promo summary::-webkit-details-marker { display: none; }
.promo summary .acc-ic { margin-left: auto; }
.promo-form { display: flex; gap: 8px; padding: 0 14px 14px; }
.promo-form .input { height: 44px; }
.promo-form .btn { height: 44px; }
.form-msg { margin: 0 14px 14px; font-size: 14px; font-weight: 600; }
.form-msg.is-ok { color: var(--navy); }
.form-msg.is-error { color: var(--error); }
.sum-trust { display: grid; gap: 10px; font-size: 13.5px; color: var(--muted); }
.sum-trust li { display: flex; align-items: center; gap: 10px; }
.sum-trust .ic { color: var(--navy); }

/* ---------- Checkout ---------- */
.checkout { padding: 40px 0 var(--section); background: #fff; }
.checkout-head { display: flex; align-items: center; justify-content: space-between; gap: 24px; flex-wrap: wrap; margin-bottom: 32px; }
.checkout-layout { display: grid; grid-template-columns: minmax(0, 1fr) 400px; gap: 48px; align-items: start; }
.checkout-form { display: flex; flex-direction: column; gap: 20px; min-width: 0; }
.co-section { padding: 28px; border: 1px solid var(--border); border-radius: var(--r-lg); }
.co-legend { display: flex; align-items: center; gap: 12px; font-size: 20px; font-weight: 700; color: var(--navy); margin-bottom: 20px; float: left; width: 100%; }
.co-legend + * { clear: both; }
.co-num { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%; background: var(--navy); color: #fff; font-size: 15px; }
.field-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px 20px; }
.field-grid-address { grid-template-columns: repeat(6, minmax(0, 1fr)); }
.field-grid-address > .field { grid-column: span 2; }
.field-grid-address > .field-wide { grid-column: span 3; }
.field { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.field-full { grid-column: 1 / -1; }
.field > label { font-size: 15px; font-weight: 600; }
.optional { font-weight: 400; color: var(--muted); }
.hint { font-size: 13px; color: var(--muted); }
.error { display: flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 600; color: var(--error); }
.has-error .input { border-color: var(--error); box-shadow: inset 0 0 0 1px var(--error); }
.billing-slot:not(:empty) { margin-top: 16px; }
.billing { margin-top: 16px; padding-top: 20px; border-top: 1px solid var(--border); }
.billing-title { font-size: 16px; font-weight: 700; margin-bottom: 16px; }
.radio-cards { display: grid; gap: 10px; }
.radio-card { position: relative; display: flex; align-items: center; gap: 14px; min-height: 64px; padding: 14px 18px; border: 1.5px solid var(--border); border-radius: var(--r-md); cursor: pointer; transition: border-color .15s, background-color .15s; }
.radio-card:hover { border-color: var(--sky-light); }
.radio-card.is-active { border-color: var(--navy); background: var(--page); box-shadow: inset 0 0 0 1px var(--navy); }
.radio-card input { position: absolute; opacity: 0; inset: 0; width: 100%; height: 100%; margin: 0; cursor: pointer; }
.radio-card:has(input:focus-visible) { outline: 2px solid var(--navy); outline-offset: 2px; }
.radio-dot { width: 22px; height: 22px; border-radius: 50%; border: 1.5px solid var(--control); background: #fff; flex: none; }
.radio-card.is-active .radio-dot { border-color: var(--navy); box-shadow: inset 0 0 0 5px var(--navy); }

